  "El episodio {episode} tiene {count} pistas de audio y el primero tiene {first}. dvdauthor usa el layout del primer título.": "O episódio {episode} tem {count} faixas de áudio e o primeiro tem {first}. O dvdauthor usa o layout do primeiro título.",
  "El episodio {episode} referencia audio externo; el encoder usa el stream embebido del vídeo.": "O episódio {episode} referencia áudio externo; o codificador usa o stream incorporado no vídeo.",
  "El episodio {episode} tiene subtítulos internos; se extraerán del vídeo con FFmpeg antes de multiplexarlos.": "O episódio {episode} tem legendas internas; serão extraídas do vídeo com FFmpeg antes da multiplexagem.",
  "Se activó Half-D1 automáticamente: duración {duration} ms y bitrate calculado {bitrate} kbps.": "Half-D1 foi ativado automaticamente: duração {duration} ms e bitrate calculado {bitrate} kbps.",
  "El bitrate calculado {bitrate} kbps supera el máximo {max} kbps; el disco quedará por debajo del objetivo de llenado.": "O bitrate calculado {bitrate} kbps excede o máximo {max} kbps; o disco ficará abaixo do objetivo de preenchimento.",
  "D1 está forzado pero el bitrate calculado ({bitrate} kbps) es inferior a {min} kbps.": "D1 está forçado, mas o bitrate calculado ({bitrate} kbps) é inferior a {min} kbps.",
  "El episodio {episode} se limita a {bitrate} kbps para respetar el máximo total de DVD con sus pistas de audio.": "O episódio {episode} está limitado a {bitrate} kbps para respeitar o máximo total de DVD com as suas faixas de áudio.",
  "El plan solo llena el {percent}% de la capacidad efectiva; el contenido es demasiado corto para alcanzar el 99% sin superar el bitrate máximo.": "O plano só preenche {percent}% da capacidade efetiva; o conteúdo é demasiado curto para atingir 99% sem exceder o bitrate máximo.",
  "El plan no es viable con el perfil y presupuesto actuales.": "O plano não é viável com o perfil e o orçamento atuais.",
