  "Muestra las herramientas avanzadas: animación, mapa de la máquina virtual y calidad VBR": "Affiche les outils avancés : animation, carte de la machine virtuelle et qualité VBR",
  "O elige cualquier imagen o vídeo en «Medios» (panel izquierdo) y pulsa «Miniatura».": "Ou choisissez une image ou une vidéo dans « Médias » (panneau de gauche) et cliquez sur « Miniature ».",
