  "Con DVD Forge conviertes tus vídeos en un disco con menú, como los de las películas. Son 5 pasos y esta guía te acompaña en cada uno.": "Avec DVD Forge, vous transformez vos vidéos en un disque avec menu, comme ceux des films. Il y a 5 étapes et ce guide vous accompagne à chacune.",
  "Puedes abrir esta guía cuando quieras con el botón ❓ Guía de arriba.": "Vous pouvez rouvrir ce guide à tout moment avec le bouton ❓ Guide en haut.",
  "Todo se guarda en un archivo de proyecto; tus vídeos originales nunca se modifican.": "Tout est enregistré dans un fichier de projet ; vos vidéos originales ne sont jamais modifiées.",
  "DVD funciona en casi cualquier reproductor y consola. Blu-ray/AVCHD tiene imagen en alta definición (HD) y necesita un reproductor Blu-ray, PS3/PS4/PS5 o similar.": "Le DVD fonctionne sur presque tous les lecteurs et consoles. Le Blu-ray/AVCHD offre une image haute définition (HD) et nécessite un lecteur Blu-ray, une PS3/PS4/PS5 ou équivalent.",
  "¿Dudas? Elige DVD-Video: es el más compatible.": "Un doute ? Choisissez DVD-Video : c'est le plus compatible.",
  "Para Blu-ray, usa 1080p. Si tus vídeos son de TV o de un móvil europeo elige 25 fps; si son de EE. UU./América, 29,97 fps.": "Pour le Blu-ray, utilisez 1080p. Si vos vidéos viennent d'une TV ou d'un téléphone européens, choisissez 25 i/s ; pour les États-Unis/Amériques, 29,97 i/s.",
  "En el panel izquierdo (pestaña «Medios») pulsa «+ Importar» y elige tus vídeos. Después pulsa «+ Episodio» en cada uno para ponerlo en el disco.": "Dans le panneau de gauche (onglet « Médias »), cliquez sur « + Importer » et choisissez vos vidéos. Cliquez ensuite sur « + Épisode » pour chacune afin de l'ajouter au disque.",
  "Los episodios aparecen abajo, en la barra de Secuencia, en el orden en que se reproducirán. Usa ‹ › para reordenarlos.": "Les épisodes apparaissent en bas, dans la barre Séquence, dans l'ordre de lecture. Utilisez ‹ › pour les réordonner.",
  "En Edición puedes recortar el principio y el final de cada vídeo y añadir capítulos.": "Dans Montage, vous pouvez couper le début et la fin de chaque vidéo et ajouter des chapitres.",
