  "Para cambiar el fondo, elige una imagen en «Medios» y pulsa «Fondo».": "Pour changer le fond, choisissez une image dans « Médias » et cliquez sur « Fond ».",
  "Para la miniatura de un botón: selecciónalo y pulsa «Usar imagen de…» en el Inspector (derecha).": "Pour la miniature d'un bouton : sélectionnez-le et cliquez sur « Utiliser l'image de… » dans l'Inspecteur (à droite).",
  "¿Quieres otra pantalla de menú? Pulsa «+ Pantalla de menú» en la barra de abajo.": "Un autre écran de menu ? Cliquez sur « + Écran de menu » dans la barre du bas.",
  "El Simulador muestra el disco tal como funcionará en el reproductor. Usa las flechas del teclado y Enter, o el mando de la pantalla.": "Le Simulateur montre le disque tel qu'il fonctionnera sur le lecteur. Utilisez les flèches du clavier et Entrée, ou la télécommande à l'écran.",
  "Si un botón no se puede alcanzar con las flechas, el simulador te lo avisa.": "Si un bouton est inaccessible avec les flèches, le simulateur vous prévient.",
  "En Pistas puedes elegir idiomas de audio y añadir subtítulos (.srt, .ass, .vtt).": "Dans Pistes, vous pouvez choisir les langues audio et ajouter des sous-titres (.srt, .ass, .vtt).",
  "Pulsa «Producir disco» (arriba a la derecha). DVD Forge prepara un archivo ISO y, si tienes grabadora, puede grabarlo directamente.": "Cliquez sur « Produire le disque » (en haut à droite). DVD Forge prépare un fichier ISO et, si vous avez un graveur, peut le graver directement.",
  "La barra de capacidad indica cuánto ocupa el disco. Si se pasa, prueba un disco de doble capa (DVD-9 o BD-50).": "La barre de capacité indique le remplissage du disque. S'il déborde, essayez un disque double couche (DVD-9 ou BD-50).",
  "Antes de grabar, el disco se comprueba automáticamente para evitar discos defectuosos.": "Avant la gravure, le disque est vérifié automatiquement pour éviter les disques défectueux.",
  "Si algo falla, el botón ⚕ Salud te dice qué herramienta falta (por ejemplo, FFmpeg).": "En cas de problème, le bouton ⚕ Santé indique quel outil manque (par exemple FFmpeg).",
  "Elige el tipo de disco. Si no estás seguro, DVD-Video funciona en casi cualquier reproductor.": "Choisissez le type de disque. En cas de doute, le DVD-Video fonctionne sur presque tous les lecteurs.",
