  "Convierte tus vídeos en un DVD o Blu-ray con menú, como los de las películas: importa, diseña el menú, pruébalo con el mando y graba.": "Machen Sie aus Ihren Videos eine DVD oder Blu-ray mit Menü, wie bei Filmen: importieren, Menü gestalten, mit der Fernbedienung testen und brennen.",
