  "Muestra las herramientas avanzadas: animación, mapa de la máquina virtual y calidad VBR": "Zeigt die erweiterten Werkzeuge: Animation, Karte der virtuellen Maschine und VBR-Qualität",
  "O elige cualquier imagen o vídeo en «Medios» (panel izquierdo) y pulsa «Miniatura».": "Oder wählen Sie ein Bild oder Video in „Medien“ (linkes Feld) und klicken Sie auf „Vorschaubild“.",
