  "¿Cómo funciona?": "Wie funktioniert es?",
  "Con DVD Forge conviertes tus vídeos en un disco con menú, como los de las películas. Son 5 pasos y esta guía te acompaña en cada uno.": "Mit DVD Forge machen Sie aus Ihren Videos eine Disc mit Menü, wie bei Filmen. Es sind 5 Schritte, und diese Anleitung begleitet Sie bei jedem.",
  "Puedes abrir esta guía cuando quieras con el botón ❓ Guía de arriba.": "Sie können diese Anleitung jederzeit über die Schaltfläche ❓ Anleitung oben öffnen.",
  "Todo se guarda en un archivo de proyecto; tus vídeos originales nunca se modifican.": "Alles wird in einer Projektdatei gespeichert; Ihre Originalvideos werden nie verändert.",
  "DVD funciona en casi cualquier reproductor y consola. Blu-ray/AVCHD tiene imagen en alta definición (HD) y necesita un reproductor Blu-ray, PS3/PS4/PS5 o similar.": "DVD läuft auf fast jedem Player und jeder Konsole. Blu-ray/AVCHD bietet HD-Bild und braucht einen Blu-ray-Player, eine PS3/PS4/PS5 oder Ähnliches.",
  "¿Dudas? Elige DVD-Video: es el más compatible.": "Unsicher? Wählen Sie DVD-Video: das ist am kompatibelsten.",
  "Para Blu-ray, usa 1080p. Si tus vídeos son de TV o de un móvil europeo elige 25 fps; si son de EE. UU./América, 29,97 fps.": "Für Blu-ray 1080p verwenden. Stammen Ihre Videos aus europäischem TV oder von europäischen Handys, wählen Sie 25 fps; für USA/Amerika 29,97 fps.",
  "En el panel izquierdo (pestaña «Medios») pulsa «+ Importar» y elige tus vídeos. Después pulsa «+ Episodio» en cada uno para ponerlo en el disco.": "Klicken Sie im linken Feld (Registerkarte „Medien“) auf „+ Importieren“ und wählen Sie Ihre Videos. Klicken Sie dann bei jedem auf „+ Episode“, um es auf die Disc zu setzen.",
  "Los episodios aparecen abajo, en la barra de Secuencia, en el orden en que se reproducirán. Usa ‹ › para reordenarlos.": "Die Episoden erscheinen unten in der Leiste „Sequenz“ in Wiedergabereihenfolge. Mit ‹ › ändern Sie die Reihenfolge.",
  "En Edición puedes recortar el principio y el final de cada vídeo y añadir capítulos.": "Unter „Bearbeitung“ können Sie Anfang und Ende jedes Videos kürzen und Kapitel hinzufügen.",
  "En la pestaña Menú ves la pantalla que aparecerá en la tele. Lo más fácil: abre la pestaña «Plantillas» del panel izquierdo (o la galería debajo del menú) y elige una; DVD Forge crea un botón por episodio.": "Die Registerkarte „Menü“ zeigt den Bildschirm, der auf dem Fernseher erscheint. Am einfachsten: Öffnen Sie links die Registerkarte „Vorlagen“ (oder die Galerie unter dem Menü) und wählen Sie eine; DVD Forge erstellt eine Schaltfläche pro Episode.",
  "Para cambiar el fondo, elige una imagen en «Medios» y pulsa «Fondo».": "Um den Hintergrund zu ändern, wählen Sie ein Bild in „Medien“ und klicken Sie auf „Hintergrund“.",
  "Para la miniatura de un botón: selecciónalo y pulsa «Usar imagen de…» en el Inspector (derecha).": "Für das Vorschaubild einer Schaltfläche: Schaltfläche wählen und im Inspektor (rechts) auf „Bild von … verwenden“ klicken.",
  "¿Quieres otra pantalla de menú? Pulsa «+ Pantalla de menú» en la barra de abajo.": "Noch ein Menübildschirm? Klicken Sie unten in der Leiste auf „+ Menübildschirm“.",
  "El Simulador muestra el disco tal como funcionará en el reproductor. Usa las flechas del teclado y Enter, o el mando de la pantalla.": "Der Simulator zeigt die Disc genau so, wie sie im Player funktioniert. Verwenden Sie die Pfeiltasten und Enter oder die Bildschirm-Fernbedienung.",
  "Si un botón no se puede alcanzar con las flechas, el simulador te lo avisa.": "Ist eine Schaltfläche mit den Pfeilen nicht erreichbar, weist der Simulator darauf hin.",
  "En Pistas puedes elegir idiomas de audio y añadir subtítulos (.srt, .ass, .vtt).": "Unter „Spuren“ wählen Sie Audiosprachen und fügen Untertitel hinzu (.srt, .ass, .vtt).",
  "Pulsa «Producir disco» (arriba a la derecha). DVD Forge prepara un archivo ISO y, si tienes grabadora, puede grabarlo directamente.": "Klicken Sie auf „Disc erstellen“ (oben rechts). DVD Forge erstellt eine ISO-Datei und kann sie mit einem Brenner direkt brennen.",
  "La barra de capacidad indica cuánto ocupa el disco. Si se pasa, prueba un disco de doble capa (DVD-9 o BD-50).": "Der Kapazitätsbalken zeigt die Belegung der Disc. Ist sie zu voll, nehmen Sie eine Double-Layer-Disc (DVD-9 oder BD-50).",
  "Antes de grabar, el disco se comprueba automáticamente para evitar discos defectuosos.": "Vor dem Brennen wird die Disc automatisch geprüft, um fehlerhafte Discs zu vermeiden.",
  "Si algo falla, el botón ⚕ Salud te dice qué herramienta falta (por ejemplo, FFmpeg).": "Wenn etwas fehlschlägt, zeigt die Schaltfläche ⚕ Status, welches Werkzeug fehlt (zum Beispiel FFmpeg).",
  "Elige el tipo de disco. Si no estás seguro, DVD-Video funciona en casi cualquier reproductor.": "Wählen Sie den Disc-Typ. Im Zweifel läuft DVD-Video auf fast jedem Player.",
