  "¿Cómo funciona?": "Come funziona?",
  "Con DVD Forge conviertes tus vídeos en un disco con menú, como los de las películas. Son 5 pasos y esta guía te acompaña en cada uno.": "Con DVD Forge trasformi i tuoi video in un disco con menu, come quelli dei film. Sono 5 passi e questa guida ti accompagna in ognuno.",
  "Puedes abrir esta guía cuando quieras con el botón ❓ Guía de arriba.": "Puoi aprire questa guida quando vuoi con il pulsante ❓ Guida in alto.",
  "Todo se guarda en un archivo de proyecto; tus vídeos originales nunca se modifican.": "Tutto viene salvato in un file di progetto; i tuoi video originali non vengono mai modificati.",
  "DVD funciona en casi cualquier reproductor y consola. Blu-ray/AVCHD tiene imagen en alta definición (HD) y necesita un reproductor Blu-ray, PS3/PS4/PS5 o similar.": "Il DVD funziona su quasi tutti i lettori e le console. Blu-ray/AVCHD offre immagini in alta definizione (HD) e richiede un lettore Blu-ray, una PS3/PS4/PS5 o simili.",
  "¿Dudas? Elige DVD-Video: es el más compatible.": "Dubbi? Scegli DVD-Video: è il più compatibile.",
  "Para Blu-ray, usa 1080p. Si tus vídeos son de TV o de un móvil europeo elige 25 fps; si son de EE. UU./América, 29,97 fps.": "Per il Blu-ray usa 1080p. Se i tuoi video provengono da TV o telefoni europei scegli 25 fps; per USA/Americhe 29,97 fps.",
  "En el panel izquierdo (pestaña «Medios») pulsa «+ Importar» y elige tus vídeos. Después pulsa «+ Episodio» en cada uno para ponerlo en el disco.": "Nel pannello sinistro (scheda «Media») premi «+ Importa» e scegli i tuoi video. Poi premi «+ Episodio» su ciascuno per metterlo sul disco.",
  "Los episodios aparecen abajo, en la barra de Secuencia, en el orden en que se reproducirán. Usa ‹ › para reordenarlos.": "Gli episodi compaiono in basso, nella barra Sequenza, nell'ordine di riproduzione. Usa ‹ › per riordinarli.",
  "En Edición puedes recortar el principio y el final de cada vídeo y añadir capítulos.": "In Modifica puoi tagliare l'inizio e la fine di ogni video e aggiungere capitoli.",
  "En la pestaña Menú ves la pantalla que aparecerá en la tele. Lo más fácil: abre la pestaña «Plantillas» del panel izquierdo (o la galería debajo del menú) y elige una; DVD Forge crea un botón por episodio.": "La scheda Menu mostra la schermata che apparirà sulla TV. La cosa più semplice: apri la scheda «Modelli» del pannello sinistro (o la galleria sotto il menu) e scegline uno; DVD Forge crea un pulsante per episodio.",
  "Para cambiar el fondo, elige una imagen en «Medios» y pulsa «Fondo».": "Per cambiare lo sfondo, scegli un'immagine in «Media» e premi «Sfondo».",
  "Para la miniatura de un botón: selecciónalo y pulsa «Usar imagen de…» en el Inspector (derecha).": "Per la miniatura di un pulsante: selezionalo e premi «Usa l'immagine di…» nell'Ispettore (a destra).",
  "¿Quieres otra pantalla de menú? Pulsa «+ Pantalla de menú» en la barra de abajo.": "Vuoi un'altra schermata di menu? Premi «+ Schermata di menu» nella barra in basso.",
  "El Simulador muestra el disco tal como funcionará en el reproductor. Usa las flechas del teclado y Enter, o el mando de la pantalla.": "Il Simulatore mostra il disco esattamente come funzionerà nel lettore. Usa le frecce della tastiera e Invio, oppure il telecomando sullo schermo.",
  "Si un botón no se puede alcanzar con las flechas, el simulador te lo avisa.": "Se un pulsante non è raggiungibile con le frecce, il simulatore te lo segnala.",
  "En Pistas puedes elegir idiomas de audio y añadir subtítulos (.srt, .ass, .vtt).": "In Tracce puoi scegliere le lingue audio e aggiungere sottotitoli (.srt, .ass, .vtt).",
  "Pulsa «Producir disco» (arriba a la derecha). DVD Forge prepara un archivo ISO y, si tienes grabadora, puede grabarlo directamente.": "Premi «Produci disco» (in alto a destra). DVD Forge prepara un file ISO e, se hai un masterizzatore, può masterizzarlo direttamente.",
  "La barra de capacidad indica cuánto ocupa el disco. Si se pasa, prueba un disco de doble capa (DVD-9 o BD-50).": "La barra della capacità indica quanto è pieno il disco. Se è troppo pieno, prova un disco a doppio strato (DVD-9 o BD-50).",
  "Antes de grabar, el disco se comprueba automáticamente para evitar discos defectuosos.": "Prima della masterizzazione il disco viene verificato automaticamente per evitare dischi difettosi.",
  "Si algo falla, el botón ⚕ Salud te dice qué herramienta falta (por ejemplo, FFmpeg).": "Se qualcosa non va, il pulsante ⚕ Stato ti dice quale strumento manca (per esempio FFmpeg).",
  "Elige el tipo de disco. Si no estás seguro, DVD-Video funciona en casi cualquier reproductor.": "Scegli il tipo di disco. Se non sei sicuro, il DVD-Video funziona su quasi tutti i lettori.",
  "Funciona en casi todos los reproductores, consolas y ordenadores. Calidad estándar.": "Funziona su quasi tutti i lettori, le console e i computer. Qualità standard.",
  "Blu-ray / AVCHD (alta definición)": "Blu-ray / AVCHD (alta definizione)",
  "Imagen HD con menús. Necesita reproductor Blu-ray, PS3/PS4/PS5 o similar.": "Immagine HD con menu. Richiede un lettore Blu-ray, una PS3/PS4/PS5 o simili.",
  "NTSC · 720×480 (América, Japón)": "NTSC · 720×480 (Nord America, Giappone)",
