  "El barrido (progresivo/entrelazado) no coincide con el proyecto; se recodifica.": "La scansione (progressiva/interlacciata) non corrisponde al progetto; verrà ricodificato.",
  "El episodio está recortado al principio; para copiar sin recodificar no puede haber recorte inicial.": "L'episodio è tagliato all'inizio; per copiare senza ricodificare non deve esserci un taglio iniziale.",
  "El bitrate del vídeo es desconocido o supera el máximo del disco; se recodifica.": "Il bitrate del video è sconosciuto o supera il massimo del disco; verrà ricodificato.",
