  "subtítulo": "字幕",
  "El episodio {episode} tiene {count} pistas de audio y el primero tiene {first}. dvdauthor usa el layout del primer título.": "エピソード {episode} の音声トラックは {count} 本で、最初のエピソードは {first} 本です。dvdauthor は最初のタイトルのレイアウトを使用します。",
  "El episodio {episode} referencia audio externo; el encoder usa el stream embebido del vídeo.": "エピソード {episode} は外部音声を参照しています。エンコーダーは動画に埋め込まれたストリームを使用します。",
  "El episodio {episode} tiene subtítulos internos; se extraerán del vídeo con FFmpeg antes de multiplexarlos.": "エピソード {episode} には内部字幕があります。多重化の前に FFmpeg で動画から抽出されます。",
  "Se activó Half-D1 automáticamente: duración {duration} ms y bitrate calculado {bitrate} kbps.": "Half-D1 が自動的に有効になりました: 長さ {duration} ms、計算ビットレート {bitrate} kbps。",
  "El bitrate calculado {bitrate} kbps supera el máximo {max} kbps; el disco quedará por debajo del objetivo de llenado.": "計算ビットレート {bitrate} kbps が最大 {max} kbps を超えています。ディスクは目標の充填率を下回ります。",
  "D1 está forzado pero el bitrate calculado ({bitrate} kbps) es inferior a {min} kbps.": "D1 が強制されていますが、計算ビットレート ({bitrate} kbps) が {min} kbps 未満です。",
  "El episodio {episode} se limita a {bitrate} kbps para respetar el máximo total de DVD con sus pistas de audio.": "エピソード {episode} は音声トラックを含めた DVD の合計最大値を守るため、{bitrate} kbps に制限されています。",
  "El plan solo llena el {percent}% de la capacidad efectiva; el contenido es demasiado corto para alcanzar el 99% sin superar el bitrate máximo.": "プランは実効容量の {percent}% しか埋めません。最大ビットレートを超えずに 99% に到達するには内容が短すぎます。",
  "El plan no es viable con el perfil y presupuesto actuales.": "現在のプロファイルと予算ではプランは実行できません。",
  "Los subtítulos externos de AVCHD/Blu-ray se conservan en el proyecto, pero todavía no se multiplexan en la imagen.": "外部 AVCHD/Blu-ray 字幕はプロジェクトに保持されますが、まだイメージに多重化されていません。",
  "El episodio {episode} tiene varias pistas de audio; AVCHD usará la primera.": "エピソード {episode} には複数の音声トラックがあります。AVCHD は最初のトラックを使用します。",
  "El bitrate calculado {bitrate} kbps supera el máximo de {max} kbps para {capacity}; el disco quedará por debajo del objetivo de llenado.": "計算ビットレート {bitrate} kbps が {capacity} の最大 {max} kbps を超えています。ディスクは目標の充填率を下回ります。",
  "Más de 5 horas de contenido: considera resolución SD para conservar calidad y capacidad.": "5 時間を超える内容です。品質と容量を保つため SD 解像度を検討してください。",
  "El plan llena el {percent}% de la capacidad efectiva de {capacity}; el contenido es demasiado corto para aprovecharla.": "プランは {capacity} の実効容量の {percent}% を埋めます。内容が短すぎて活用できません。",
  "El plan AVCHD supera el presupuesto del disco.": "AVCHD プランがディスク予算を超えています。",
  "El First Play referencia un asset inexistente; no se reserva espacio para la intro.": "First Play が存在しないアセットを参照しています。イントロ用の領域は確保されません。",
  "No se pudo determinar la duración de la intro; no se reserva espacio.": "イントロの長さを特定できませんでした。領域は確保されません。",
