  "Ideal para TV y video casero. Se graba como PsF (imagen progresiva en señal 1080i), compatible con todos los reproductores Blu-ray.": "テレビ番組や家庭用ビデオに最適。PsF（1080i 信号内のプログレッシブ映像）で記録され、すべての Blu-ray プレーヤーで再生できます。",
