  "Los botones {a} y {b} se solapan o no tienen 4 px de separación.": "ボタン {a} と {b} が重なっているか、間隔が 4 px 未満です。",
  "Los encoders se confirman con un frame de prueba; si fallan, el render cae a CPU.": "エンコーダーはテストフレームで確認されます。失敗した場合は CPU でレンダリングします。",
