  "Máxima fluidez (deportes, videojuegos, cámaras modernas). Es AVCHD 2.0: funciona en PS3/PS4/PS5 y reproductores actuales, pero algunos Blu-ray antiguos no lo reproducen.": "最もなめらか（スポーツ、ゲーム、最新カメラ）。AVCHD 2.0 のため PS3/PS4/PS5 や最近のプレーヤーで再生できますが、古い Blu-ray プレーヤーでは再生できない場合があります。",
